def encender_las_que_mlb_publica(apps, schema_editor):
    """Deja encendidas de arranque las métricas que MLB sí publica como ranking.

    El flag nace apagado para las 203 del catálogo, y así el widget nacería vacío. Se encienden las
    veintitrés que tienen categoría en MLB —ni una más— y el dueño apaga desde el Backoffice las que
    no quiera. Es más fácil quitar de una lista que ya se ve, que adivinar cuáles faltan.
    """
    from dglweb.stats.mlb_leaders import CATEGORIAS

    Metric = apps.get_model("stats", "Metric")
    for grupo, columna in set(CATEGORIAS.values()):
        Metric.objects.filter(stat_group=grupo, column=columna).update(visible_en_widget_lideres=True)


def apagarlas(apps, schema_editor):
    apps.get_model("stats", "Metric").objects.update(visible_en_widget_lideres=False)


